import {bindConversationWindow} from './ui/conversation-window.js';
import {renderMarkdown} from './ui/markdown.js';
import {VoiceCoreController} from './ui/voice-core.js';
import {VolcVoice} from './volc-voice.js';
import {voiceProvider} from './voice-provider.js';
const aliases={'#callPanel':'#assistantDrawer','#messages':'#assistantMessages','#chatForm':'#assistantForm','#chatInput':'#assistantInput','#closeCall':'#closeAssistant','#minCall':'#minAssistant','#maxCall':'#maxAssistant','#floatingCall':'#restoreAssistant'};
const $=s=>document.querySelector(document.body.dataset.unified?(aliases[s]||s):s);
export class VoiceController{
 constructor(opts){Object.assign(this,opts);this.mode='local';this.state='idle';this.generation=0;this.history=opts.history||[];this.speaking=false;this.muted=false;this.busy=false;this.captions={partial:text=>{const draft=$('#callDraft');draft.textContent=text?'你：'+text:'';draft.hidden=!text}};voiceProvider();this.visualizer=new VoiceCoreController([$('#voiceCoreMain'),$('#voiceCoreCall')],{reducedMotion:document.body.classList.contains('reduced')});this.motionObserver=new MutationObserver(()=>this.visualizer.setReducedMotion(document.body.classList.contains('reduced')));this.motionObserver.observe(document.body,{attributes:true,attributeFilter:['class']});this.bind();document.addEventListener('jarvis:quote',e=>this.selectedSymbol=e.detail.quote?.symbol);this.volc=new VolcVoice({api:this.api,onAudioGraph:taps=>this.visualizer.setTaps(taps),onOutputReset:()=>this.visualizer.resetOutput(),onVoiceState:facts=>this.syncVolc(facts),status:t=>this.status(t),onPartial:t=>this.captions.partial(t),message:(role,t)=>{if(role==='user')this.captions.partial('');this.addMessage(role,t,'小木')},context:()=>this.getContext?.()?.symbol||this.selectedSymbol,onJobs:jobs=>{if(jobs.length)localStorage.setItem('jarvis-research-job',jobs[0].id);this.onTool?.()}});if(!this.preserveHistory)this.addMessage('assistant','五简，我在。');}
 syncVolc(facts){this.state=facts.connection==='error'?'idle':facts.connection;this.speaking=facts.agentSpeaking;this.muted=facts.micMuted;this.visualizer.setState(facts);document.body.dataset.voiceState=facts.connection==='connected'?(facts.agentSpeaking?'speaking':'connected'):facts.connection;$('#connectCall').disabled=['connecting','connected'].includes(facts.connection);$('#connectCall').textContent=facts.connection==='connected'?'已接通':facts.connection==='connecting'?'连接中…':'接通';$('#hangup').disabled=!['connecting','connected'].includes(facts.connection);$('#stopCall').disabled=facts.connection!=='connected';if($('#muteCall')){$('#muteCall').disabled=facts.connection!=='connected';$('#muteCall').textContent=facts.micMuted?'取消静音':'静音';$('#muteCall').setAttribute('aria-pressed',String(facts.micMuted))}if(facts.connection==='connected'&&!this.timer){this.started=Date.now();this.timer=setInterval(()=>{const t=Math.floor((Date.now()-this.started)/1000);$('#callTime').textContent=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0')},1000)}if(facts.connection!=='connected'){clearInterval(this.timer);this.timer=null;$('#callTime').textContent='00:00'}}
 bind(){bindConversationWindow({panel:$('#callPanel'),minimize:$('#minCall'),maximize:$('#maxCall'),close:$('#closeCall'),onMinimize:()=>{$('#callPanel').hidden=true;$('#floatingCall').hidden=false},onClose:()=>{this.stop();$('#callPanel').hidden=true;$('#floatingCall').hidden=true}});$('#floatingCall').onclick=()=>this.open();$('#connectCall').onclick=()=>this.openCall();$('#stopCall').onclick=()=>this.interrupt();$('#hangup').onclick=()=>this.stop();if($('#muteCall'))$('#muteCall').onclick=()=>this.mute();$('#chatForm').onsubmit=e=>{e.preventDefault();const text=$('#chatInput').value.trim();if(!text)return;$('#chatInput').value='';void this.submit(text)};}
 open(){$('#callPanel').classList.remove('voice-only');document.body.classList.remove('voice-focus');$('#callPanel').hidden=false;$('#floatingCall').hidden=true;$('#chatInput').focus()}
 showCall(){this.open()}
 openCall(){this.showCall();if(!['connected','connecting'].includes(this.state))void this.connect()}
 setMode(mode){if(this.mode===mode)return;if(this.state!=='idle')this.stop();this.mode=mode;}
 status(text){$('#callStatus').textContent=text;document.body.dataset.voiceState=this.speaking?'speaking':this.state}
 phase(value){this.status(({working:'DeepSeek正在查询与思考',listening:'正在聆听',speaking:'正在播报'})[value]||value)}
 addMessage(role,text,label='小木'){const log=$('#messages'),selection=window.getSelection?.(),follow=log.scrollHeight-log.scrollTop-log.clientHeight<70&&(!selection||selection.isCollapsed||!log.contains(selection.anchorNode));const d=document.createElement('div');d.className='bubble '+(role==='user'?'user':'');const s=document.createElement('small');s.textContent=role==='user'?'你':label;const p=document.createElement('div');if(role==='user')p.textContent=text;else renderMarkdown(p,text);d.append(s,p);log.append(d);this.onMessage?.(role,text);if(follow)log.scrollTop=log.scrollHeight;return p}
 async submit(text){if(/^(停一下|停止播报|别说了)[。！!]?$/u.test(text.trim())){this.interrupt();return}if(this.busy){this.addMessage('assistant','上一条问题正在处理，请稍等。已启动的研究任务在后台继续。');return}
 this.addMessage('user',text);this.busy=true;const gen=this.generation;this.phase('working');
 try{const messages=[...this.history.slice(-20),{role:'user',content:text}];const context=this.getContext?.()||{};const result=await this.api('/api/chat',{messages,contextSymbol:context.symbol,cardId:context.card});if(gen!==this.generation)return;if(result.jobs?.length)localStorage.setItem('jarvis-research-job',result.jobs[0].id);this.history=[...messages,{role:'assistant',content:result.text}].slice(-20);this.addMessage('assistant',result.text);this.onMonitorDrafts?.(result.monitorDrafts);this.status('DeepSeek V4.1 Flash · 已回复');if(this.state==='connected'&&this.recognition)this.speak(result.text);await this.onTool?.();}catch(e){if(gen===this.generation){this.addMessage('assistant',e.message||'DeepSeek暂不可用');this.status('模型请求失败 · 可重试')}}finally{if(gen===this.generation)this.busy=false;}
 }
 async connect(){if(['connected','connecting'].includes(this.state))return;const provider=voiceProvider();if(provider==='browser'&&!window.xiaomuMonitor&&(window.SpeechRecognition||window.webkitSpeechRecognition))return this.connectBrowser();this.stop();this.mode='ai';return this.volc.connect();}
 async connectBrowser(){if(this.state!=='idle')return;if(!(window.SpeechRecognition||window.webkitSpeechRecognition)){this.status('当前浏览器不支持语音识别 · DeepSeek文字可用');return}if(!this.isConfigured()){this.status('DeepSeek尚未配置');return}this.setMode('ai');this.visualizer.setState({connection:'connecting'});this.state='connecting';const gen=++this.generation;this.busy=false;$('#connectCall').disabled=true;
 try{const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}});if(gen!==this.generation){stream.getTracks().forEach(t=>t.stop());return}this.stream=stream;this.startLocal();}catch{if(gen!==this.generation)return;this.stop();this.status('麦克风未就绪 · DeepSeek文字仍可用')}
 }
 startLocal(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;const gen=this.generation;this.recognition=new SR();this.recognition.lang='zh-CN';this.recognition.continuous=true;this.recognition.interimResults=false;
 this.recognition.onresult=e=>{if(gen!==this.generation||this.speaking||this.muted)return;for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)void this.submit(e.results[i][0].transcript)};
 this.recognition.onerror=e=>{if(['not-allowed','service-not-allowed','network','audio-capture'].includes(e.error)){this.stop();this.status('浏览器语音识别失败 · DeepSeek文字仍可用')}};
 this.recognition.onend=()=>{clearTimeout(this.listenTimer);if(gen===this.generation&&this.state==='connected'&&!this.muted&&!this.speaking)this.listenTimer=setTimeout(()=>{if(gen===this.generation)try{this.recognition?.start()}catch{}},350)};
 this.recognition.start();this.visualizer.setState({connection:'connected'});this.state='connected';this.started=Date.now();this.status('已连接 · DeepSeek语音助手');$('#hangup').disabled=false;$('#stopCall').disabled=false;$('#connectCall').textContent='已接通';this.timer=setInterval(()=>{const t=Math.floor((Date.now()-this.started)/1000);$('#callTime').textContent=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');if(t>=900)this.stop()},1000);
 }
 speak(text){if(!this.recognition||!window.speechSynthesis||this.state!=='connected')return;this.speaking=true;this.phase('speaking');try{this.recognition?.stop()}catch{};speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';u.rate=1.03;const gen=this.generation;u.onend=u.onerror=()=>{if(gen!==this.generation)return;this.speaking=false;this.resumeListening()};speechSynthesis.speak(u);}
 resumeListening(){if(this.recognition&&this.state==='connected'&&!this.muted){this.phase('listening');try{this.recognition?.start()}catch{}}}
 interrupt(){this.volc?.interrupt();window.speechSynthesis?.cancel();this.speaking=false;this.resumeListening();}
 mute(){this.muted=!this.muted;this.volc?.mute(this.muted);this.stream?.getAudioTracks().forEach(t=>t.enabled=!this.muted);this.visualizer.setState({micMuted:this.muted});if(this.muted){try{this.recognition?.stop()}catch{}}else this.resumeListening();}
 stop(){this.captions?.partial('');this.volc?.stop();this.generation++;this.busy=false;clearTimeout(this.listenTimer);clearInterval(this.timer);this.timer=null;this.state='idle';if(this.recognition){this.recognition.onend=null;this.recognition.onresult=null;this.recognition.onerror=null;try{this.recognition.stop()}catch{}}this.recognition=null;this.stream?.getTracks().forEach(t=>t.stop());this.stream=null;window.speechSynthesis?.cancel();this.speaking=false;this.muted=false;$('#connectCall').disabled=false;$('#connectCall').textContent='接通';$('#hangup').disabled=true;$('#stopCall').disabled=true;$('#callTime').textContent='00:00';this.visualizer.setState({connection:'idle',agentSpeaking:false,userSpeaking:false,working:false,micMuted:false});if($('#muteCall')){$('#muteCall').disabled=true;$('#muteCall').textContent='静音';$('#muteCall').setAttribute('aria-pressed','false')}this.status('通话已结束');}
}
